-- 0002_auth: Better Auth core tables (generated by better-auth 1.7.7 getMigrations for D1,
-- then hardened: role is NOT NULL with a CHECK). test/auth-schema.test.ts fails if this drifts
-- from what Better Auth expects.

CREATE TABLE "user" (
  "id" text NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "email" text NOT NULL UNIQUE,
  "emailVerified" integer NOT NULL,
  "image" text,
  "createdAt" date NOT NULL,
  "updatedAt" date NOT NULL,
  "role" text NOT NULL DEFAULT 'USER' CHECK ("role" IN ('USER', 'ADMIN'))
);

CREATE TABLE "session" (
  "id" text NOT NULL PRIMARY KEY,
  "expiresAt" date NOT NULL,
  "token" text NOT NULL UNIQUE,
  "createdAt" date NOT NULL,
  "updatedAt" date NOT NULL,
  "ipAddress" text,
  "userAgent" text,
  "userId" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE
);

CREATE TABLE "account" (
  "id" text NOT NULL PRIMARY KEY,
  "accountId" text NOT NULL,
  "providerId" text NOT NULL,
  "userId" text NOT NULL REFERENCES "user" ("id") ON DELETE CASCADE,
  "accessToken" text,
  "refreshToken" text,
  "idToken" text,
  "accessTokenExpiresAt" date,
  "refreshTokenExpiresAt" date,
  "scope" text,
  "password" text,
  "createdAt" date NOT NULL,
  "updatedAt" date NOT NULL
);

CREATE TABLE "verification" (
  "id" text NOT NULL PRIMARY KEY,
  "identifier" text NOT NULL,
  "value" text NOT NULL,
  "expiresAt" date NOT NULL,
  "createdAt" date NOT NULL,
  "updatedAt" date NOT NULL
);

CREATE INDEX "session_userId_idx" ON "session" ("userId");
CREATE INDEX "account_userId_idx" ON "account" ("userId");
CREATE INDEX "verification_identifier_idx" ON "verification" ("identifier");

-- Per-account login backoff. key = HMAC(secret, lower(email)): no raw emails stored here, and
-- the row exists whether or not the account does (no enumeration signal).
CREATE TABLE login_throttle (
  key          TEXT PRIMARY KEY,
  failures     INTEGER NOT NULL,
  locked_until INTEGER NOT NULL DEFAULT 0,
  updated_at   INTEGER NOT NULL
) STRICT;

-- Security events, retained >= 1 year (DPDP Rules) because platform logs keep only 3 days.
-- Identifiers are HMACed; user_id only when authenticated.
CREATE TABLE security_events (
  id           TEXT PRIMARY KEY,
  type         TEXT NOT NULL,
  user_id      TEXT,
  subject_hash TEXT,
  ip_hash      TEXT,
  request_id   TEXT NOT NULL,
  created_at   INTEGER NOT NULL
) STRICT;

CREATE INDEX idx_security_events_created ON security_events (created_at);
CREATE INDEX idx_security_events_user ON security_events (user_id, created_at);
